// Order-8 IIR, TRANSPOSED feedforward chain: one multiply+add per stage
// (registered partial sums) + a tiny feedback stage -> critical path roughly
// independent of the order -> high Fmax. Same function as the direct form.
module iir8_v7 (
  input clk, input rst_n, input [7:0] x, output reg [15:0] y
);
  reg [15:0] r0;
  reg [15:0] r1;
  reg [15:0] r2;
  reg [15:0] r3;
  reg [15:0] r4;
  reg [15:0] r5;
  reg [15:0] r6;
  reg [15:0] r7;
  reg [15:0] r8;
  reg [15:0] y2;
  wire [31:0] acc = 57*x + r0 + ((9*y)>>4) + ((5*y2)>>4);
  always @(posedge clk) begin
    if (!rst_n) begin y<=0; y2<=0; r0<=0; r1<=0; r2<=0; r3<=0; r4<=0; r5<=0; r6<=0; r7<=0; r8<=0; end
    else begin
      y <= acc[15:0];
      y2 <= y;
      r0 <= (40*x + r1) & 16'hFFFF;
      r1 <= (15*x + r2) & 16'hFFFF;
      r2 <= (4*x + r3) & 16'hFFFF;
      r3 <= (33*x + r4) & 16'hFFFF;
      r4 <= (61*x + r5) & 16'hFFFF;
      r5 <= (39*x + r6) & 16'hFFFF;
      r6 <= (57*x + r7) & 16'hFFFF;
      r7 <= (30*x + r8) & 16'hFFFF;
      r8 <= (57*x) & 16'hFFFF;
    end
  end
endmodule
